/* SHP local delivery evidence workspace. Blobs remain in IndexedDB via ctx.files. */
window.SHDeliveries=(()=>{
 const pages=['Deliveries & evidence','Damage & missing items','Kitset upgrades'];
 const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const uid=()=>crypto.randomUUID();
 const photoTypes=['image/jpeg','image/png','image/webp'];
 const documentTypes=['application/pdf','image/jpeg','image/png'];
 let objectUrls=[];
 function init(c){for(const key of ['shipments','freightIncidents','deliveryReceipts','upgrades','upgradeSelections','inventory','suppliers'])if(!Array.isArray(c.store[key]))c.store[key]=[];}
 const projectId=c=>c.projectId||c.project?.id;
 const own=(c,key)=>c.store[key].filter(x=>x.projectId===projectId(c));
 const input=(name,label,type='text',extra='')=>`<label>${escape(label)}<input name="${name}" type="${type}" ${extra}></label>`;
 const textarea=(name,label)=>`<label>${escape(label)}<textarea name="${name}" rows="3" maxlength="4000"></textarea></label>`;
 const files=()=>`<div class="delivery-file-fields"><label>Kitset photos · JPEG, PNG or WebP<input name="photos" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><label>Signed consignment document · PDF, JPEG or PNG<input name="consignment" type="file" accept="application/pdf,image/jpeg,image/png" multiple></label></div><p class="small">Up to 10 files per record, 10 MB per file. Files stay in this browser on this device. No server upload or outbound notification occurs. Supply an actual signed document; this preview cannot create signatures.</p>`;
 const evidence=record=>`<div class="delivery-evidence" data-evidence-owner="${escape(record.id)}">${(record.attachments||[]).map(a=>`<div class="delivery-attachment" data-evidence-id="${escape(a.id)}"><strong>${escape(a.kind==='consignment'?'Signed consignment':'Kitset photo')}: ${escape(a.name)}</strong><span class="small"> ${Math.ceil(a.size/1024)} KB · Local only</span><div class="delivery-file-preview">Loading local evidence…</div></div>`).join('')||'<p class="small">No evidence attached.</p>'}</div>`;
 const shipmentOptions=c=>own(c,'shipments').map(s=>`<option value="${escape(s.id)}">${escape(s.carrier||'Carrier not entered')} · ${escape(s.trackingNumber||s.id)} · ${escape(s.destination||'Destination pending')}</option>`).join('');
 const shipmentSelect=c=>`<label>Project shipment<select name="shipmentId" required><option value="">Select shipment</option>${shipmentOptions(c)}</select></label>`;
 function safeLink(value){try{const u=new URL(value);return u.protocol==='https:'?u.href:'';}catch{return '';}}
 function render(page,c){init(c);for(const u of objectUrls)URL.revokeObjectURL(u);objectUrls=[];if(!pages.includes(page))return '';let body='';
 if(page==='Deliveries & evidence')body=`<div class="delivery-notice"><strong>Check your kitset on arrival</strong><p>Compare delivery against the manifest, photograph the load and retain the signed consignment document. These local records are planning evidence, not a carrier claim or proof of automatic acceptance.</p></div><section class="card"><h2>Project shipments</h2>${own(c,'shipments').map(s=>{const url=safeLink(s.trackingUrl);return `<article class="delivery-item"><h3>${escape(s.carrier||'Carrier to be confirmed')} · ${escape(s.status||'Status pending')}</h3><p>${escape(s.origin||'Origin pending')} → ${escape(s.destination||'Destination pending')} · ${escape(s.region||'Region pending')}</p><p><strong>Expected: ${escape(s.expectedDate||'Not scheduled')}</strong> · Tracking reference: ${escape(s.trackingNumber||'Not supplied')}</p>${url?`<a class="secondary" href="${escape(url)}" target="_blank" rel="noopener noreferrer">Open carrier tracking ↗</a><p class="small">External carrier link. Portal status and events are manually recorded; no live carrier connection.</p>`:'<p class="small">No valid HTTPS tracking link. Portal status is manually recorded.</p>'}<details><summary>Expected delivery manifest (${(s.manifest||[]).length} items)</summary><div class="table-wrap"><table><thead><tr><th>Expected item</th><th>Quantity / unit</th></tr></thead><tbody>${(s.manifest||[]).map(m=>`<tr><td>${escape(m.item)}</td><td>${escape(m.qty)} ${escape(m.unit)}</td></tr>`).join('')||'<tr><td colspan="2">Manifest awaiting Shed House.</td></tr>'}</tbody></table></div></details><details><summary>Manually recorded shipment events</summary>${(s.events||[]).slice().sort((a,b)=>String(b.at).localeCompare(String(a.at))).map(e=>`<p><strong>${escape(e.status)}</strong> · ${escape(e.location)} · ${escape(e.at)}<br>${escape(e.note)} · Manual entry</p>`).join('')||'<p>No events recorded.</p>'}</details></article>`;}).join('')||'<p>No shipments have been added to your project by Shed House.</p>'}</section><form id="delivery-receipt-form" class="card delivery-form"><h2>Record delivery receipt</h2>${shipmentSelect(c)}${input('receivedAt','Received date and time','datetime-local','required')}${input('receivedBy','Received by','text','required maxlength="150"')}<label>Condition on arrival<select name="condition"><option>Not inspected</option><option>Appears complete and undamaged</option><option>Damage observed</option><option>Items missing</option><option>Damage and missing items</option></select></label>${textarea('notes','Delivery notes and manifest differences')}${files()}<label class="delivery-check"><input type="checkbox" name="draft"> Save as draft: signed consignment document not yet available</label><p class="small">A completed receipt requires at least one kitset photo and a signed consignment document. Drafts remain visibly incomplete and can be completed with evidence later.</p><p class="delivery-error" role="alert"></p><button class="primary">Save local receipt</button></form><section class="card"><h2>Delivery evidence records</h2>${own(c,'deliveryReceipts').map(r=>`<article class="delivery-item"><h3>${escape(r.receivedAt)} · ${escape(r.receivedBy)}</h3><span class="tag ${r.status==='Draft'?'amber':''}">${escape(r.status||'Recorded')}</span><p>${escape(r.condition)} · ${escape(r.notes)}</p>${r.status==='Draft'?'<p class="delivery-warning">Draft — signed consignment document or kitset photos still required.</p>':''}${evidence(r)}<details><summary>Add evidence to this receipt</summary><form class="delivery-form" data-add-receipt="${escape(r.id)}">${files()}<p class="delivery-error" role="alert"></p><button class="secondary">Save additional local evidence</button></form></details></article>`).join('')||'<p>No delivery receipts saved yet.</p>'}</section>`;
 if(page==='Damage & missing items')body=`<section class="delivery-notice"><h2>Report a delivery issue</h2><ol><li>Check quantities and specifications against your delivery manifest and kitset inventory.</li><li>Photograph the affected item, identifying labels, packaging and the wider load. Record what was expected and what arrived.</li><li>Retain damaged goods and packaging. Do not install parts that may be unsafe; request Shed House assessment and replacement guidance.</li><li>Keep the signed consignment document and note the difference with the carrier when possible.</li><li>Check the carrier’s specific reporting deadline and terms promptly. Saving this local report does not submit a carrier claim; contact Shed House and the carrier separately.</li></ol></section><form id="delivery-incident-form" class="card delivery-form"><h2>Damage / missing item report</h2>${shipmentSelect(c)}<label>Issue type<select name="type"><option>Damage</option><option>Missing items</option><option>Damage and missing items</option></select></label><label>Manifest item<select name="manifestItem"><option value="">Select a shipment first</option></select></label><p class="small" id="manifest-expected">Choose a manifest item to see its expected quantity.</p>${input('item','Affected item / specification','text','required maxlength="200"')}${input('expectedQty','Expected quantity','number','min="0" step="0.01" required')}${input('qty','Observed quantity received','number','min="0" step="0.01" required')}${textarea('description','Damage, shortage and circumstances')}${input('carrierDeadline','Carrier-specific reporting deadline / terms reference','text','maxlength="250"')}${files()}<p class="delivery-error" role="alert"></p><button class="primary">Save issue & notify project parties locally</button></form><section class="card"><h2>Issue register</h2>${own(c,'freightIncidents').map(r=>`<article class="delivery-item"><h3>${escape(r.type)} · ${escape(r.item)}</h3><span class="tag amber">${escape(r.status)}</span><p>Expected ${escape(r.expectedQty??'Not recorded')} · Observed ${escape(r.qty)} ${escape(r.unit||'')}</p><p>${escape(r.description)}</p><p>Case reference: ${escape(r.caseReference||'Awaiting assessment')} · Decision: ${escape(r.decision||'Awaiting Shed House assessment')}</p><p class="small">Carrier terms: ${escape(r.carrierDeadline||'Check carrier-specific deadline promptly')}</p>${evidence(r)}<details><summary>Case history</summary>${(r.history||[]).map(h=>`<p>${escape(h.at)} · ${escape(h.by||h.owner||'Project party')} · ${escape(h.status)} · ${escape(h.note||'')}</p>`).join('')}</details></article>`).join('')||'<p>No reported freight issues for this project.</p>'}</section>`;
 if(page==='Kitset upgrades'){const rate=Number(c.store.fees?.gstRate??15);body=`<div class="delivery-notice"><strong>Explore optional kitset upgrades</strong><p>Request interest for Shed House to assess availability, compatibility, pricing and programme impact. An interest request does not change your agreed scope, place an order or authorise work.</p></div><div class="delivery-catalogue">${c.store.upgrades.filter(u=>['active','available'].includes(String(u.status).toLowerCase())).map(u=>{const supplier=c.store.suppliers.find(s=>s.id===u.supplierId);const price=u.priceExGst==null||u.priceExGst===''?NaN:Number(u.priceExGst);return `<section class="card"><div class="eyebrow">${escape(u.category)}</div><h2>${escape(u.name)}</h2><p>${escape(u.description)}</p><p>Additional to contracted kitset baseline. Confirm scope before selection.<br>Supplier: ${escape(supplier?.name||'Confirm with Shed House')}</p><p><strong>${Number.isFinite(price)?`NZD ${price.toFixed(2)} excl GST`:'Price to be confirmed'}</strong>${Number.isFinite(price)?`<br>NZD ${(price*(1+rate/100)).toFixed(2)} incl ${escape(rate)}% GST`:''}</p><button class="primary" data-request-upgrade="${escape(u.id)}">Request upgrade assessment</button></section>`;}).join('')||'<section class="card"><p>No active upgrades published by Shed House yet.</p></section>'}</div><section class="card"><h2>Your upgrade requests</h2>${own(c,'upgradeSelections').map(s=>`<article class="delivery-item"><h3>${escape(c.store.upgrades.find(u=>u.id===s.upgradeId)?.name||'Upgrade')}</h3><p>${escape(s.status)} · ${escape(s.createdAt)}</p><p class="small">${s.priceSnapshot==null?'Price not set':`Price snapshot NZD ${escape(s.priceSnapshot)} excl GST`} · Subject to Shed House assessment and agreed variation.</p></article>`).join('')||'<p>No upgrade requests yet.</p>'}</section>`;}
 return `<div class="customer-deliveries"><div class="heading"><div><div class="eyebrow">CUSTOMER · LOCAL DEMONSTRATION</div><h1>${escape(page)}</h1><p>${escape(c.project?.name||projectId(c))}</p></div></div>${body}</div>`;
 }
 function validateFiles(list,existing=0){if(list.length+existing>10)throw Error('Maximum 10 files per record.');for(const {file,kind} of list){if(file.size>10*1024*1024)throw Error(`${file.name}: maximum file size is 10 MB.`);if(file.size===0)throw Error(`${file.name}: empty files cannot be saved.`);if(!(kind==='photo'?photoTypes:documentTypes).includes(file.type))throw Error(`${file.name}: unsupported file type.`);}}
 function selectedFiles(form){return ['photos','consignment'].flatMap(name=>Array.from(form.elements[name]?.files||[]).map(file=>({file,kind:name==='photos'?'photo':'consignment'})));}
 async function saveFiles(c,ownerId,list){const attachments=[];try{for(const {file,kind} of list){const record={id:uid(),projectId:projectId(c),ownerId,kind,name:file.name,type:file.type,size:file.size,blob:file,createdAt:new Date().toISOString()};const key=await c.files.put(record);attachments.push({id:key||record.id,name:record.name,type:record.type,size:record.size,kind});}return attachments;}catch(e){await Promise.allSettled(attachments.map(a=>c.files.remove(a.id)));throw e;}}
 function bind(page,c){init(c);const save=()=>{c.save();c.navigate(page);};const notify=(title,message,kind)=>c.notify({title,message,kind,projectId:projectId(c),roles:['staff','customer','contractor']});
 async function submit(form,handler){const button=form.querySelector('button');const error=form.querySelector('.delivery-error');if(button.disabled)return;button.disabled=true;error.textContent='';try{if(!c.files)throw Error('Local evidence storage is unavailable in this browser.');await handler();}catch(e){error.textContent=e.message||'Could not save local evidence. Please try again.';button.disabled=false;}}
 const receipt=document.getElementById('delivery-receipt-form');if(receipt)receipt.onsubmit=e=>{e.preventDefault();submit(receipt,async()=>{const d=Object.fromEntries(new FormData(receipt));if(!own(c,'shipments').some(s=>s.id===d.shipmentId))throw Error('Choose a shipment for this project.');const list=selectedFiles(receipt);validateFiles(list);if(!d.draft&&(!list.some(x=>x.kind==='photo')||!list.some(x=>x.kind==='consignment')))throw Error('Attach a kitset photo and actual signed consignment document, or save an incomplete draft.');const record={id:uid(),projectId:projectId(c),shipmentId:d.shipmentId,receivedAt:d.receivedAt,receivedBy:d.receivedBy.trim(),condition:d.condition,notes:d.notes,status:d.draft?'Draft':'Recorded',attachments:[]};record.attachments=await saveFiles(c,record.id,list);c.store.deliveryReceipts.push(record);notify('Delivery receipt saved',`${record.receivedBy}: ${record.condition}. ${record.status==='Draft'?'Incomplete draft; evidence still required.':'Evidence recorded locally.'}`,'delivery');save();});};
 document.querySelectorAll('[data-add-receipt]').forEach(form=>form.onsubmit=e=>{e.preventDefault();submit(form,async()=>{const record=own(c,'deliveryReceipts').find(r=>r.id===form.dataset.addReceipt);if(!record)throw Error('Receipt is no longer available.');const list=selectedFiles(form);if(!list.length)throw Error('Select evidence to add.');validateFiles(list,record.attachments?.length||0);const attachments=await saveFiles(c,record.id,list);record.attachments=[...(record.attachments||[]),...attachments];record.status=record.attachments.some(a=>a.kind==='photo')&&record.attachments.some(a=>a.kind==='consignment')?'Recorded':'Draft';notify('Delivery evidence added',`Receipt for ${record.receivedBy}: ${record.status}.`,'delivery');save();});});
 const incident=document.getElementById('delivery-incident-form');if(incident){const shipment=incident.elements.shipmentId;const manifest=incident.elements.manifestItem;const update=()=>{const s=own(c,'shipments').find(x=>x.id===shipment.value);manifest.innerHTML='<option value="">Select manifest item (or describe below)</option>'+(s?.manifest||[]).map((m,i)=>`<option value="${i}">${escape(m.item)}</option>`).join('');document.getElementById('manifest-expected').textContent='Choose a manifest item to see its expected quantity.';};shipment.onchange=update;manifest.onchange=()=>{const s=own(c,'shipments').find(x=>x.id===shipment.value),m=s?.manifest?.[Number(manifest.value)];if(manifest.value===''||!m)return;incident.elements.namedItem('item').value=m.item;incident.elements.expectedQty.value=m.qty;document.getElementById('manifest-expected').textContent=`Expected: ${m.qty} ${m.unit||''}. Check what actually arrived.`;};incident.onsubmit=e=>{e.preventDefault();submit(incident,async()=>{const d=Object.fromEntries(new FormData(incident));const shipment=own(c,'shipments').find(s=>s.id===d.shipmentId);if(!shipment)throw Error('Choose a shipment for this project.');if(!d.description.trim())throw Error('Describe the damage or shortage.');if(!Number.isFinite(Number(d.qty))||Number(d.qty)<0||!Number.isFinite(Number(d.expectedQty))||Number(d.expectedQty)<0)throw Error('Enter valid non-negative quantities.');const list=selectedFiles(incident);validateFiles(list);const m=d.manifestItem===''?null:shipment.manifest?.[Number(d.manifestItem)];const record={id:uid(),projectId:projectId(c),shipmentId:d.shipmentId,inventoryId:m?.inventoryId||null,type:d.type,item:d.item,qty:Number(d.qty),expectedQty:Number(d.expectedQty),unit:m?.unit||'',description:d.description,carrierDeadline:d.carrierDeadline,hold:true,status:'Reported',createdAt:new Date().toISOString(),attachments:[],owner:'customer',decision:'',caseReference:'',history:[]};record.attachments=await saveFiles(c,record.id,list);record.history.push({at:record.createdAt,by:'customer',status:'Reported',note:'Local report saved; carrier claim not submitted.'});c.store.freightIncidents.push(record);shipment.status='On hold';shipment.events||=[];shipment.events.push({id:uid(),status:'On hold',location:shipment.destination,note:'Customer freight report: '+record.type,at:record.createdAt,source:'Customer report'});notify('Kitset delivery issue reported',`${record.type}: ${record.item}; expected ${record.expectedQty}, observed ${record.qty}. Shed House assessment required.`,'freight');save();});};}
 document.querySelectorAll('[data-request-upgrade]').forEach(button=>button.onclick=()=>{const u=c.store.upgrades.find(x=>x.id===button.dataset.requestUpgrade&&['active','available'].includes(String(x.status).toLowerCase()));if(!u)return;if(own(c,'upgradeSelections').some(s=>s.upgradeId===u.id&&s.status==='Requested'))return c.toast('Assessment already requested for this upgrade.');c.store.upgradeSelections.push({id:uid(),projectId:projectId(c),upgradeId:u.id,priceSnapshot:u.priceExGst!=null&&u.priceExGst!==''&&Number.isFinite(Number(u.priceExGst))?Number(u.priceExGst):null,status:'Requested',createdAt:new Date().toISOString()});notify('Kitset upgrade assessment requested',`${u.name}: review scope, price, compatibility and programme before any agreed variation.`,'upgrade');save();});
 document.querySelectorAll('[data-evidence-id]').forEach(async el=>{const area=el.querySelector('.delivery-file-preview');try{const record=await c.files?.get(el.dataset.evidenceId);if(!record?.blob||record.projectId!==projectId(c)){area.textContent='Evidence unavailable on this device.';return;}const owner=el.closest('[data-evidence-owner]')?.dataset.evidenceOwner;if(record.ownerId!==owner){area.textContent='Evidence reference mismatch.';return;}if(!el.isConnected)return;const url=URL.createObjectURL(record.blob);objectUrls.push(url);area.textContent='';if(photoTypes.includes(record.type)){const img=document.createElement('img');img.src=url;img.alt=record.name;img.className='delivery-photo';area.append(img);}else if(record.type==='application/pdf'){const text=document.createElement('p');text.textContent='Signed PDF stored locally. Open or download to review.';area.append(text);}const a=document.createElement('a');a.href=url;a.download=record.name;a.className='secondary';a.textContent='Download evidence';area.append(a);const open=document.createElement('a');open.href=url;open.target='_blank';open.rel='noopener noreferrer';open.className='secondary';open.textContent='Open evidence';area.append(open);}catch{area.textContent='Could not read local evidence.';}});
 }
 return {pages,render,bind};
})();
